import json
O='/workspace/eight-bit-adder/design/gates/'
HDR="<!-- viewBox 0 0 60 40. Pins: in A (0,12), in B (0,28), out (60,20). Stroke = currentColor; body fill via class 'body'. -->"
def svg(name,leads,body,extra=''):
    return (f"<svg class='gate gate-{name}' viewBox='0 0 60 40' width='60' height='40' fill='none' stroke='currentColor' stroke-width='2.4' stroke-linecap='round' stroke-linejoin='round'>"
            f"{HDR}<path class='lead lead-a' d='{leads[0]}'/><path class='lead lead-b' d='{leads[1]}'/><path class='lead lead-out' d='{leads[2]}'/>"
            f"{extra}<path class='body' d='{body}'/></svg>")
# slightly wobbly hand-drawn coordinates (deliberately not perfectly symmetric)
AND=svg('and',["M0 12 C5 11.6 10 12.4 15 12","M0 28 C5 28.4 10 27.7 15 28","M47.5 20 C51 19.6 56 20.4 60 20"],
        "M14.6 5.8 C20 5.4 26 6.2 30.5 6 C42 6.4 47.8 13 47.6 20.2 C47.4 27.6 41.5 34.2 30 34 C25 33.8 19.5 34.4 14.4 34.1 C14.9 24.5 14.2 15 14.6 5.8Z")
OR=svg('or',["M0 12 C6 11.6 12 12.3 18 12","M0 28 C6 28.3 12 27.6 18 28","M47.6 20 C51 20.4 56 19.6 60 20"],
       "M12.2 5.9 C24 5.6 38.5 9 47.8 20 C38.3 31.2 24.5 34.5 12 34.2 C17.6 24.8 17.9 15.2 12.2 5.9Z")
XOR=svg('xor',["M0 12 C6 11.6 14 12.3 21 12","M0 28 C6 28.3 14 27.6 21 28","M48 20 C51.5 20.4 56 19.6 60 20"],
        "M16.4 5.9 C27.5 5.7 39.5 9.2 48.2 20 C39.3 31 27.8 34.4 16.2 34.2 C21.6 24.9 21.9 15.3 16.4 5.9Z",
        extra="<path class='back' d='M10.3 5.8 C15.8 14.8 16 25.4 10.1 34.3'/>")
NOTHDR="<!-- viewBox 0 0 60 40. Pins: in A (0,20), out (60,20). Stroke = currentColor; body fill via class 'body'. on = output 1 (input 0). -->"
NOT=(f"<svg class='gate gate-not' viewBox='0 0 60 40' width='60' height='40' fill='none' stroke='currentColor' stroke-width='2.4' stroke-linecap='round' stroke-linejoin='round'>"
     f"{NOTHDR}<path class='lead lead-a' d='M0 20 C5 19.6 11 20.4 16 20'/><path class='lead lead-out' d='M50.6 20 C53 20.4 57 19.6 60 20'/>"
     f"<path class='body' d='M15.6 7.2 C25 11.6 34 15.8 42.4 20 C34 24.4 25 28.6 15.8 32.8 C16.2 24 15.3 15.8 15.6 7.2Z'/>"
     f"<circle class='body bubble' cx='46.6' cy='20' r='3.8'/></svg>")
G={'and':AND,'or':OR,'xor':XOR,'not':NOT}
for k,v in G.items(): open(O+k+'.svg','w').write(v.replace("<svg ","<svg xmlns='http://www.w3.org/2000/svg' ",1))
open(O+'gates.js','w').write("// Generated by gates-gen.py. Gate SVG strings (single quotes only).\n// viewBox 0 0 60 40; pins: A (0,12), B (0,28), out (60,20); NOT: in (0,20), out (60,20). Toggle class 'on' on the <svg class='gate'>.\n"
 "// Load as a classic script: sets window.GATES = {and, or, xor} (also module.exports under Node).\n"
 "(function(){var GATES="+json.dumps(G,indent=1)+";\n if(typeof window!=='undefined')window.GATES=GATES;\n if(typeof module!=='undefined')module.exports=GATES;})();\n")
